  source: 'pragma solidcash ^0.51.0;\n\n/// One MiMC hash, proved in its own input.\n///\n/// A deposit needs 20 hashes and one input\'s op budget holds one, so the pool spends\n/// a row of these coins beside its master. The pool reads `left`, `right` and `out`\n/// from the fixed offsets of this input\'s unlocking bytecode: three 32-byte pushes\n/// in reverse argument order.\n///\n/// `mimc` is the precompile scripts/lib/mimc-script.ts generates: circomlib\'s\n/// MiMCSponge(2, 220, 1) over the BN254 scalar field, the circuit\'s tree hash.\n///\n/// The code names no pool, so every pool shares one lock and anyone can make a coin\n/// of it. A coin recreates itself at its own index with its value and no token,\n/// whatever else the transaction holds, so no transaction can take its value, or\n/// leave it with a token, which would stop a client reading it.\n///\n/// A coin that has not moved for SWEEP_AGE blocks can be swept by anyone, but only\n/// as its transaction\'s only input. A pool\'s transaction always has more inputs, so\n/// every coin a pool reads has proved its hash.\ncontract MimcHash {\n    /// About ten days of blocks.\n    int constant SWEEP_AGE = 1440;\n\n    function hash(bytes32 left, bytes32 right, bytes32 out) public {\n        if (tx.inputs.length == 1) {\n            require(this.age >= SWEEP_AGE, "age");\n        } else {\n            uint32 coin = this.activeInputIndex;\n            require(tx.outputs[coin].lockingBytecode == tx.inputs[coin].lockingBytecode, "coin");\n            require(tx.outputs[coin].value == tx.inputs[coin].value, "coin");\n            require(tx.outputs[coin].tokenCategory.length == 0, "coin");\n            require(mimc(abi.encodePacked(left, right)) == out, "mimc");\n        }\n    }\n}\n',
